package com.scriptles.cabinet.profile.entity;
import com.scriptles.cabinet.profile.enums.HQClaimRequestStatus; import com.scriptles.cabinet.user.entity.User; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="hq_claims",indexes=@Index(name="idx_hq_claims_status",columnList="status,created_at")) @Getter @Setter @NoArgsConstructor
public class HQClaim { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="hq_profile_id",nullable=false) private HQProfile hqProfile; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="requested_by_account_id",nullable=false) private User requestedBy; @Column(nullable=false,length=254) private String organizationEmail; @Column(length=500) private String evidenceUrl; @Column(columnDefinition="TEXT") private String message; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private HQClaimRequestStatus status=HQClaimRequestStatus.PENDING; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="reviewed_by_account_id") private User reviewedBy; private Instant reviewedAt; @CreationTimestamp private Instant createdAt; @UpdateTimestamp private Instant updatedAt; }
